/// Converts `input` to a URL‑friendly slug by:
/// - lowercasing
/// - replacing spaces with `-`
/// - keeping only `[a-z0-9-]`
fn slugify(input: &str) -> String {
    input
        .to_lowercase()
        .chars()
        .filter_map(|c| {
            if c == ' ' {
                Some('-')
            } else if c.is_ascii_alphanumeric() || c == '-' {
                Some(c)
            } else {
                None
            }
        })
        .collect()
}

#[cfg(test)]
mod tests {
    use super::*;

    #[test]
    fn basic_hello_world() {
        assert_eq!(slugify("Hello World"), "hello-world");
    }

    #[test]
    fn strips_special_characters() {
        assert_eq!(slugify("Foo Bar! Baz"), "foo-bar-baz");
    }

    #[test]
    fn keeps_numbers_and_existing_dashes() {
        assert_eq!(slugify("123-Go Now"), "123-go-now");
    }
}
