/// Converts the input string into a URL-friendly slug.
///
/// * Lowercases all characters.
/// * Replaces spaces with hyphens (`-`).
/// * Removes all characters except lowercase letters `a-z`, digits `0-9`, and hyphens.
pub fn slugify(input: &str) -> String {
    input
        .chars()
        .map(|c| c.to_ascii_lowercase())
        .filter_map(|c| {
            if c.is_ascii_alphanumeric() || c == '-' {
                Some(c)
            } else if c == ' ' {
                Some('-')
            } else {
                None
            }
        })
        .collect()
}

#[cfg(test)]
mod tests {
    use super::*;

    #[test]
    fn test_basic() {
        assert_eq!(slugify("Hello World"), "hello-world");
    }

    #[test]
    fn test_numbers_and_dashes() {
        assert_eq!(slugify("ABC-123 xYz"), "abc-123-xyz");
    }

    #[test]
    fn test_special_chars() {
        // Spaces and special characters: space becomes '-', others removed.
        assert_eq!(slugify("Test!@# Space"), "test--space");
    }
}
